    r: rsc,
    p: isPossiblyPartialResponse,
    // The accumulator is itself the AsyncIterable<string> that Flight
    // serializes into the segment's render output.
    v: varyParamsAccumulator,
  }
  if (children !== undefined) {
    node.c = children
  }
  return node
}
