import type { AppPageRouteModule } from '../../../server/route-modules/app-page/module.compiled'
import type { AppRouteRouteModule } from '../../../server/route-modules/app-route/module.compiled'
import {
  type AppSegmentConfig,
  parseAppSegmentConfig,
} from './app-segment-config'

import { InvariantError } from '../../../shared/lib/invariant-error'
import {
  isAppRouteRouteModule,
  isAppPageRouteModule,
} from '../../../server/route-modules/checks'
import { isClientReference } from '../../../lib/client-and-server-references'
import { getSegmentParam } from '../../../shared/lib/router/utils/get-segment-param'
import {
  getLayoutOrPageModule,
  type LoaderTree,
} from '../../../server/lib/app-dir-module'
import type { DynamicParamTypes } from '../../../shared/lib/app-router-types'
import { resolveEnsureStaticConfig } from '../../../server/app-render/segment-config/ensure-static'
import { anySegmentHasPartialPrefetchingEnabled } from '../../../server/app-render/instant-validation/instant-config'
import { isPlainObject } from '../../../shared/lib/is-plain-object'

type GenerateStaticParams = (options: { params?: Params }) => Promise<Params[]>

export const PARAM_MATCHING_MODES = [
  'not-found',
  'blocking',
  'fallback',
  'dynamic',
] as const

export type ParamMatchingMode = (typeof PARAM_MATCHING_MODES)[number]

export type ParamMatching = Record<string, ParamMatchingMode>

function validateParamMatchingExport(
  route: string,
  filePath: string | undefined,
  exportName: string,
  value: unknown,
  visibleParamNames: readonly string[]
): ParamMatching {
  if (!isPlainObject(value)) {
    const valueType =
      value === null ? 'null' : Array.isArray(value) ? 'array' : typeof value
    throw new Error(
      `Invalid value from \`${exportName}\` for "${route}". Expected an object, but received ${valueType}.`
    )
  }

  const paramMatching: ParamMatching = {}
  for (const [paramName, mode] of Object.entries(
    value as Record<string, unknown>
  )) {
    if (!visibleParamNames.includes(paramName)) {
      throw new Error(
        `Invalid parameter "${paramName}" in \`${exportName}\` for "${route}". The export in "${filePath}" may only configure parameters defined at or above its segment.`
      )
    }
    if (!PARAM_MATCHING_MODES.includes(mode as ParamMatchingMode)) {
      throw new Error(
        `Invalid mode for parameter "${paramName}" in \`${exportName}\` for "${route}". Expected "not-found", "blocking", "fallback", or "dynamic", but received ${JSON.stringify(mode)}.`
      )
    }
    paramMatching[paramName] = mode as ParamMatchingMode
  }

  return paramMatching
}

/**
 * Parses the app config and attaches it to the segment.
 */
function attach(
  segment: AppSegment,
  userland: unknown,
  route: string,
  visibleParamNames: readonly string[]
) {
  // If the userland is not an object, then we can't do anything with it.
  if (typeof userland !== 'object' || userland === null) {
    return
  }

  // Try to parse the application configuration.
  const config = parseAppSegmentConfig(userland, route)

  // If there was any keys on the config, then attach it to the segment.
  if (Object.keys(config).length > 0) {
    segment.config = config
  }

  if (
    'generateStaticParams' in userland &&
    typeof userland.generateStaticParams === 'function'
  ) {
    segment.generateStaticParams =
      userland.generateStaticParams as GenerateStaticParams

    // Compiler-injected factory whose error stack is anchored at the user's
    // `generateStaticParams` declaration. Used to throw a meaningful error when
    // an empty result is detected under Cache Components.
    const createEmptyParamsError = (userland as Record<string, unknown>)
      .__next_create_empty_gsp_error
    if (typeof createEmptyParamsError === 'function') {
      segment.createEmptyParamsError = createEmptyParamsError as () => Error
    }

    // Validate that `generateStaticParams` makes sense in this context.
    if (segment.config?.runtime === 'edge') {
      throw new Error(
        'Edge runtime is not supported with `generateStaticParams`.'
      )
    }
  }

  const hasStaticParamMatching = 'unstable_paramMatching' in userland
  const hasGeneratedParamMatching = 'unstable_generateParamMatching' in userland

  if (hasStaticParamMatching || hasGeneratedParamMatching) {
    if (hasStaticParamMatching && hasGeneratedParamMatching) {
      throw new Error(
        `Route "${route}" cannot export both \`unstable_paramMatching\` and \`unstable_generateParamMatching\`.`
      )
    }

    if (hasStaticParamMatching) {
      segment.paramMatching = validateParamMatchingExport(
        route,
        segment.filePath,
        'unstable_paramMatching',
        userland.unstable_paramMatching,
        visibleParamNames
      )
    } else {
      const generate = userland.unstable_generateParamMatching
      if (typeof generate !== 'function') {
        throw new Error(
          `Route "${route}" must export \`unstable_generateParamMatching\` as a function.`
        )
      }
      const { filePath } = segment
      // Retain the module's scope without evaluating user code until static
      // path generation has established its work store and cache context.
      segment.paramMatching = async () =>
        validateParamMatchingExport(
          route,
          filePath,
          'unstable_generateParamMatching',
          await generate(),
          visibleParamNames
        )
    }
  }
}

export type AppSegment = {
  name: string
  paramName: string | undefined
  paramType: DynamicParamTypes | undefined
  filePath: string | undefined
  config: AppSegmentConfig | undefined
  paramMatching: ParamMatching | (() => Promise<ParamMatching>) | undefined
  generateStaticParams: GenerateStaticParams | undefined
  createEmptyParamsError?: () => Error
}

// Preserve parallel branches for parameter matching inheritance separately
// from the flat list used by generateStaticParams.
export type AppSegmentTree = [
  segment: AppSegment,
  parallelRoutes: AppSegmentTree[],
]

/**
 * Walks the loader tree and collects the generate parameters for each segment.
 *
 * @param routeModule the app page route module
 * @returns the segments for the app page route module
 */
async function collectAppPageSegments(
  routeModule: AppPageRouteModule,
  config: { cacheComponents: boolean; partialPrefetching: boolean } | undefined
) {
  // We keep track of unique segments, since with parallel routes, it's possible
  // to see the same segment multiple times.
  const segments: AppSegment[] = []
  const segmentTree: AppSegmentTree[] = []

  const rootLoaderTree = routeModule.userland.loaderTree

  // `ensureStatic` needs to be validated against the tree structure,
  // so we cannot compute it easily in `reduceAppConfig` after the tree
  // is turned into an array of segments
  const routeHasPartialPrefetching =
    (config?.partialPrefetching ?? false) ||
    (await anySegmentHasPartialPrefetchingEnabled(rootLoaderTree))
  const prefetchConfig = routeHasPartialPrefetching ? 'partial' : 'auto'

  const ensureStatic = await resolveEnsureStaticConfig(
    rootLoaderTree,
    routeHasPartialPrefetching
  )

  // Queue will store loader trees.
  const queue: Array<{
    loaderTree: LoaderTree
    visibleParamNames: string[]
    parentChildren: AppSegmentTree[]
  }> = [
    {
      loaderTree: rootLoaderTree,
      visibleParamNames: [],
      parentChildren: segmentTree,
    },
  ]

  while (queue.length > 0) {
    const { loaderTree, visibleParamNames, parentChildren } = queue.shift()!
    const [name, parallelRoutes] = loaderTree

    // Process current node
    const { mod: userland, filePath } = await getLayoutOrPageModule(loaderTree)
    const isClientComponent = userland && isClientReference(userland)

    const param = getSegmentParam(name)
    const currentVisibleParamNames = param
      ? [...visibleParamNames, param.paramName]
      : visibleParamNames

    const segment: AppSegment = {
      name,
      paramName: param?.paramName,
      paramType: param?.paramType,
      filePath,
      config: undefined,
      paramMatching: undefined,
      generateStaticParams: undefined,
    }

    // Only server components can have app segment configurations
